// Artefato de autoria local. Não revisa nem publica cartões.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const out = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(out, '../../..');
const inventory = JSON.parse(fs.readFileSync(path.join(root, 'data/extracted/inventory.json'), 'utf8'));
const docs = new Map(inventory.filter(x => x.status === 'ok').map(x => [x.articleId, JSON.parse(fs.readFileSync(path.join(root, 'data/extracted', x.outputFile), 'utf8'))]));
const main = 'article-d4b0c4f9d75f';
const art = 'article-94e7a19d8878', chip = 'article-eca18e5843e2', agenda = 'article-d0d500126a80', inter = 'article-48bdcebcffc6', oper = 'article-39adb0cfa84e', hci = 'article-e13c3cb65c28';
function source(id, pages, sections) {
  const d = docs.get(id);
  return { file: d.file, title: d.title, pages, sections, evidence: pages.map(n => {
    const p = d.pages.find(x => x.page === n);
    if (!p?.text) throw Error('Página sem texto: ' + id + ' / ' + n);
    return p.text;
  }) };
}
const rows = [];
function add(n, q, a, pages, sections, related = []) {
  rows.push({ id: main + '-' + String(n).padStart(2, '0'), articleId: main, question: q, answer: a,
    source: source(main, pages, sections), kind: related.length ? 'synthesis' : 'direct',
    ...(related.length ? {relatedSources: related.map(([id, ps, ss]) => ({articleId: id, source: source(id, ps, ss)}))} : {}) });
}

add(9, 'Como o princípio 1 de Safety by Design transforma responsabilidade compartilhada em medidas preventivas do prestador?',
  'O princípio [[responsabilidades do prestador]] reconhece que nenhum serviço garante segurança completa, mas exige avaliar danos conhecidos e previsíveis no desenho e na oferta do produto. Responsabilidade compartilhada não autoriza transferir todo o ônus ao usuário. O relatório anuncia oito passos preventivos; o primeiro é nomear pessoas ou equipes e tornar a segurança uma função central e mensurável. Trata-se de organizar [[capacidade institucional de prevenção]], com responsáveis, direção estratégica e ação ao longo do ciclo de vida, em vez de disponibilizar uma ferramenta para a vítima agir apenas após o dano. A referência reproduz o princípio e seu primeiro exemplo histórico integralmente.',
  [22], ['Principle 1: Service provider responsibilities', 'Principle 1.1']);
add(10, 'Quais fundamentos do princípio 2 orientam o empoderamento e a autonomia, além de oferecer um botão de bloqueio?',
  'O princípio parte da [[dignidade do usuário]] e do reconhecimento de seus interesses como consideração inalienável. Propõe desenho inclusivo que fortaleça agência e controle durante a experiência, especialmente quando a segurança estiver comprometida. Seus cinco desdobramentos abrangem ferramentas e padrões protetores, consequências para violações, alertas no momento relevante, suporte com retorno e recurso, e avaliação inclusiva antes do lançamento. Os exemplos de 2019 incluem filtros e configurações iniciais protetoras, lembretes e controles acessíveis. Assim, [[autonomia depende das condições oferecidas pelo serviço]], não de presumir que todas as pessoas conseguem descobrir e configurar sozinhas a proteção necessária.',
  [30,31,32,33], ['Principle 2: User empowerment and autonomy', 'Principle 2.1', 'Principle 2.2', 'Principle 2.3', 'Principle 2.4', 'Principle 2.5']);
add(11, 'Como o princípio 3 distingue transparência e prestação de contas de uma declaração genérica de compromisso com segurança?',
  'Transparência e prestação de contas devem permitir compreender se o serviço atua conforme os objetivos de segurança que publica e ajudar usuários a agir. O princípio exige [[práticas organizacionais verificáveis]]: formação de toda a força de trabalho, políticas acessíveis e atualizadas, interlocução com usuários e especialistas independentes, avaliações anuais com análise significativa de métricas e colaboração em tecnologia protetora. Publicar apenas uma promessa não permite avaliar execução ou resultados. Os exemplos históricos incluem formação e auditoria interna, conselhos e relatórios de aplicação de regras; o documento os oferece como [[ilustrações de implementação]], sem assegurar eficácia causal.',
  [34,35,36], ['Principle 3: Transparency and accountability']);

add(12, 'O que exige o subprincípio SbD 1.1 e como equipes Trust and Safety ilustram sua execução?',
  'O 1.1 recomenda [[nomear pessoas ou equipes e responsabilizá-las]] pela criação, avaliação, implementação e operação da política de segurança. Funções variam conforme tamanho e maturidade, mas a responsabilidade deve acompanhar todo o ciclo do serviço e constituir objetivo central e mensurável. A nota de boas práticas de 2019 descreve equipes Trust and Safety que respondem e investigam situações, desenvolvem e aplicam políticas de produto e conteúdo, articulam-se com autoridades, influenciam decisões do produto e promovem conhecimento dos recursos de proteção. Menciona liderança específica de segurança e o cargo de Chief Online Safety Officer na Microsoft. São [[exemplos históricos]], não comprovação da estrutura atual dessas empresas.',
  [22], ['Principle 1.1', 'Good practice note (Principle 1.1)']);
add(13, 'O que o SbD 1.2 demanda sobre regras e moderação, e quais boas práticas o relatório apresenta?',
  'O 1.2 pede [[padrões comunitários, termos de serviço e moderação aplicados justa e consistentemente]]. A consulta indicou que entregar regras no cadastro, com aplicação rara ou inconsistente, não basta. A visibilidade da moderação humana e de consequências rápidas também foi valorizada. Nas notas de 2019, Yubo sinaliza violações durante transmissões e oferece oportunidade de correção; ReachOut forma moderadores pares que exemplificam condutas; jogos usam recompensas e endossos para comportamento positivo; Twitch permite que transmissores escolham moderadores e oferece formação. Esses exemplos mostram diferentes meios de [[tornar normas compreensíveis e operantes]], sem estabelecer que todo mecanismo de recompensa ou moderação seja eficaz em qualquer comunidade.',
  [23], ['Principle 1.2', 'Good practice note (Principle 1.2)']);
add(14, 'Quais elementos compõem o SbD 1.3 e como as notas de boas práticas conectam denúncia, triagem e escalonamento?',
  'O 1.3 combina [[mecanismos acessíveis de denúncia no ponto de ocorrência]] com infraestrutura interna e externa de triagem e encaminhamento. Fluxos definidos ajudam a priorizar risco à vida, ilegalidade e pessoas que necessitam proteção especial. Sistemas automatizados devem manter supervisão humana e comunicar seu uso. A nota de 2019 descreve denúncias em diferentes momentos e objetos da experiência, categorização para equipes especializadas, canais para menores e escalonamento por gravidade. Também relata ocultação intermediária de conteúdo já denunciado e o programa de sinalizadores confiáveis do YouTube, com formação e revisão acelerada. A boa prática envolve [[o caminho completo da denúncia]], não apenas a existência de um formulário.',
  [24], ['Principle 1.3', 'Good practice note (Principle 1.3)']);
add(15, 'Como o SbD 1.4 organiza articulação com autoridades e apoio, e que cautela territorial acompanha os exemplos?',
  'O 1.4 recomenda [[protocolos internos claros]] para articulação com autoridades, serviços de apoio e canais de denúncia de conteúdo ilegal. O documento de 2019 pede procedimentos escritos que identifiquem exigências da jurisdição relevante, caminhos específicos de encaminhamento e formação anual e na integração de trabalhadores. As boas práticas descrevem canais exclusivos para autoridades, guias para pedidos nacionais e estrangeiros e centros de segurança com recursos de apoio locais, inclusive no momento de necessidade. O próprio texto afirma que as práticas [[diferem por jurisdição]]. Portanto, os exemplos não devem ser tratados como orientação jurídica atual ou como autorização universal para compartilhar dados.',
  [25], ['Principle 1.4', 'Good practice note (Principle 1.4)']);
add(16, 'O que diferencia a prevenção do SbD 1.5 de esperar uma denúncia, e quais práticas ilustrativas são descritas?',
  'O 1.5 pede processos para [[detectar, tornar visíveis, sinalizar e remover]] condutas, contatos e conteúdos ilegais ou danosos, visando prevenir danos antes que ocorram. O relatório descreve sinais comportamentais, análise de conversas e tecnologias que auxiliam revisão e priorização. Nas notas históricas aparecem moderação híbrida, redução de visibilidade de interações disruptivas, filtros de comentários abusivos e tecnologias para identificar material de exploração infantil. A variedade ilustra respostas de detecção, encaminhamento e redução de exposição. Não se deve inferir [[garantia automática de proteção]] ou eficácia atual: as notas são ilustrações de 2019 e o framework também exige supervisão, avaliação e respeito aos demais direitos.',
  [26,24,21], ['Principle 1.5', 'Good practice note (Principle 1.5)', 'Principle 1.3', 'V. Safety by Design Principles']);
add(17, 'Como o SbD 1.6 exige avaliação documentada de riscos e como LEGO e revisões especializadas ilustram a prática?',
  'O 1.6 recomenda [[gestão de riscos e avaliações de impacto documentadas]] para antecipar e remediar danos facilitados pelo produto. Isso permite decidir funções, moderação, encaminhamento e restrições de acordo com riscos conhecidos, ajustando fluxos e auditorias à medida que o uso muda. A nota descreve uma avaliação de cada nova função e componente na LEGO, com medidas fornecidas por equipes jurídica e de segurança infantil antes da comercialização. Também menciona revisões com especialistas internos e externos e orientações sobre fluxos de moderação. A lição é [[incorporar critérios ao processo de decisão e reavaliá-los]], e não produzir um documento estático apenas depois do lançamento.',
  [27], ['Principle 1.6', 'Good practice note (Principle 1.6)']);
add(18, 'O que são contratos sociais no SbD 1.7 e como o Safety Pledge da LEGO ilustra uma alternativa ao simples aceite?',
  'O 1.7 recomenda contratos sociais no cadastro que explicitem [[deveres e responsabilidades do serviço, do usuário e de terceiros]]. A intenção é ultrapassar o aceite de termos e políticas como simples marcação de caixa, promovendo entendimento dos compromissos recíprocos na comunidade. A nota histórica descreve o Safety Pledge da LEGO Life: usuários passam por introdução com tutoriais e dicas, assinam o compromisso e podem receber distintivos ao progredir; também relata fluxos de consentimento parental. O ponto é [[ensinar e tornar visível a reciprocidade]], sem interpretar o aceite ou o compromisso infantil como transferência da responsabilidade do prestador.',
  [28], ['Principle 1.7', 'Good practice note (Principle 1.7)']);
add(19, 'Como o SbD 1.8 equilibra segurança da informação, privacidade e segurança do usuário, e quais exemplos oferece?',
  'O 1.8 parte de que [[não se pode separar a pessoa de seus dados]]. Confidencialidade, integridade e disponibilidade precisam ser consideradas com a proteção da pessoa; segurança, privacidade e proteção do usuário devem ser complementares e equilibradas. A nota recomenda comunicação rápida e clara de incidentes, explicando natureza, extensão conhecida, investigação e meios para usuários verificarem se foram afetados, com atualizações posteriores. Também descreve o programa integrado de Trust and Safety do Quizlet, com revisão de iniciativas e filtros calibrados ao contexto, mais rigorosos em interação ao vivo. O equilíbrio exige [[avaliar consequências humanas e contexto]], e não tratar proteção de dados como finalidade isolada.',
  [29], ['Principle 1.8', 'Good practice note (Principle 1.8)']);
add(20, 'Que ferramentas, padrões iniciais e boas práticas compõem o SbD 2.1?',
  'O 2.1 pede ferramentas para gerir a própria segurança, configuradas nos [[níveis mais protetores de privacidade e segurança por padrão]]. O usuário deve poder rever preferências e controlar informações pessoais; bloqueio, silenciamento e denúncia são exemplos de controle. As notas de 2019 descrevem filtros iniciais protetores, configuração mais restritiva para menores, lembretes para revisar escolhas e avisos ao tornar o perfil público. Também mencionam centralização de configurações, denúncias por testemunhas e modo de localização oculto por padrão. A boa prática articula [[proteção inicial e escolhas revisáveis]]: exigir descoberta e configuração complexa não equivale a oferecer condições efetivas de autonomia.',
  [30], ['Principle 2.1', 'Good practice note (Principle 2.1)']);
add(21, 'Como o SbD 2.2 associa consequências a violações com educação e previsibilidade nas boas práticas?',
  'O 2.2 recomenda [[protocolos e consequências claros]] que desestimulem violações e reflitam expectativas da comunidade. Regras sem repercussões reais não bastam; participantes jovens valorizaram suspensão de contas e bloqueio de endereços IP. As notas históricas descrevem diferentes respostas: remoção de conteúdo como condição de continuidade, restrições temporárias, verificação de conta e suspensão; avisos com informação adicional antes de penalidades; interrupção de transmissões se a violação continuar; e sanções progressivas em jogos. A ideia é relacionar [[regra compreendida, possibilidade de correção e aplicação consistente]], sem concluir que punições cada vez mais fortes sejam universalmente a melhor solução ou que os exemplos de 2019 provem sua eficácia.',
  [31], ['Principle 2.2', 'Good practice note (Principle 2.2)']);
add(22, 'Como o SbD 2.3 usa tecnologia no momento relevante e que boas práticas preservam decisão informada?',
  'O 2.3 recomenda recursos técnicos que [[sinalizem riscos no momento relevante]] e estimulem interações mais seguras antes do incidente. Isso pode incluir alertas, filtragem, indicadores comportamentais e conteúdo protegido por aviso ou barreira etária, permitindo decisão informada quando cabível. A nota descreve alertas instantâneos, específicos, relevantes, privados e apoiadores; advertências em mídias sensíveis; orientações antes de publicar; e proteções diferenciadas por idade. A prevenção não se resume a apagar tudo: o texto distingue remoção de conteúdo ilegal de outras formas de [[reduzir exposição e apoiar reflexão]]. Esses exemplos históricos não eliminam a necessidade de avaliar adequação, efeitos e direitos no contexto concreto.',
  [32], ['Principle 2.3', 'Good practice note (Principle 2.3)']);
add(23, 'Qual é o alcance completo do SbD 2.4 e como boas práticas de suporte, histórico de denúncias e recurso o materializam?',
  'O 2.4 recomenda [[suporte integrado, informação sobre o andamento e resultado da denúncia e oportunidade de recurso]]. Reconhece que o bem-estar importa tanto quanto resolver a ocorrência e que quem denuncia pode se sentir exposto. A nota histórica associa atualizações à confiança e descreve opções de apoio contextual, encaminhamentos, painel que informa se a denúncia permanece ativa ou se o conteúdo foi removido ou restringido e processos de contestação. Assim, a resposta inclui [[cuidado, retorno e possibilidade de revisão]], não apenas receber e encerrar o relato. Os exemplos pertencem à edição de maio de 2019 e não asseguram funcionamento atual ou efeito comprovado.',
  [33], ['Principle 2.4', 'Good practice note (Principle 2.4)']);
add(24, 'O que exige o SbD 2.5 antes do lançamento e como a nota de design inclusivo traduz esse compromisso?',
  'O 2.5 exige avaliar funções e desenho para mitigar riscos de [[todos os usuários, especialmente os de características e capacidades distintas]], antes da liberação pública. Uma proteção deve ser utilizável por quem está em diferentes situações de vulnerabilidade e sustentar autonomia, sobretudo quando a segurança é ameaçada. A nota apresenta três orientações do toolkit de design inclusivo da Microsoft: [[reconhecer exclusão, aprender com a diversidade e resolver para uma pessoa estendendo a muitas]]. Recursos e atividades ilustram como explorar essa abordagem. Não se trata de assumir um usuário médio nem de tratar a presença de um recurso como prova de que ele é acessível e protetor para todos.',
  [33], ['Principle 2.5', 'Good practice note (Principle 2.5)']);
add(25, 'Como o SbD 3.1 distribui formação e práticas de segurança por toda a força de trabalho, e o que a LEGO exemplifica?',
  'O 3.1 pede incorporar considerações, formação e práticas de segurança nos [[papéis, funções e rotinas de todas as pessoas]] que trabalham com o produto, inclusive temporários e contratados. Isso faz da proteção um objetivo do negócio durante o desenvolvimento, em vez de uma atribuição externa à operação. A nota descreve três frentes na LEGO: curso introdutório digital obrigatório para empregados e afiliados relevantes; formação aprofundada direcionada, presencial ou remota; e avaliação anual de conformidade com comunicação à liderança e às divisões. A boa prática combina [[aprendizagem inicial, aprofundamento e verificação]], sem presumir que ter uma equipe especializada dispense os demais trabalhadores de responsabilidade.',
  [34], ['Principle 3.1', 'Good practice note (Principle 3.1)']);
add(26, 'O que o SbD 3.2 recomenda sobre políticas visíveis e atualização, e como as boas práticas ajudam a incorporá-las à experiência?',
  'O 3.2 pede políticas, termos e processos de segurança [[visíveis, fáceis de localizar, atualizados e compreensíveis]], com lembretes periódicos e opção de receber avisos sobre mudanças. A informação deve usar linguagem clara, inclusive para jovens, e preferencialmente avisos breves. A nota histórica descreve seções de segurança, recursos para responsáveis, orientações de denúncia e bloqueio e experimentos de divulgação das regras. A LEGO usa personagem e grupo de segurança para centralizar orientações e oferecer mensagens em momentos relevantes. A transparência é, portanto, [[uma comunicação contínua e situada]], e não apenas disponibilizar um documento longo no cadastro.',
  [34,35], ['Principle 3.2', 'Good practice note (Principle 3.2)']);
add(27, 'Por que o SbD 3.3 requer participação externa e quais arranjos de boas práticas ilustram essa abertura?',
  'O 3.3 recomenda [[engajamento aberto com uma base ampla de usuários, especialistas independentes e partes interessadas]] na elaboração, interpretação e avaliação de padrões. Riscos interligados e consequências imprevistas excedem a competência de qualquer serviço isolado. Canais abertos ajudam a identificar e corrigir impactos antes de lançar funções. A nota histórica cita conselho independente de confiança e segurança, participação em iniciativa intersetorial de jogos mais seguros e grupos de especialistas para questões controversas, inclusive um conselho sem acordos de confidencialidade obrigatórios. O ponto não é obter um selo externo: é [[expor decisões à crítica e ao conhecimento de públicos diversos]], sem assumir que um grupo consultado represente automaticamente toda a população.',
  [35], ['Principle 3.3', 'Good practice note (Principle 3.3)']);
add(28, 'O que deve conter a avaliação anual do SbD 3.4, além do número de denúncias, e quais exemplos de métricas aparecem?',
  'O 3.4 pede avaliação anual de abusos e [[análise pública significativa]] sobre dados de denúncias, moderação e cumprimento de regras. Contagens de volume informam escala, mas não bastam para avaliar se normas e ações reduzem comportamento danoso. A nota de 2019 descreve relatórios de aplicação de regras e métricas como prevalência de violações, conteúdo que recebeu ação, detecção antes de denúncias, velocidade e precisão; algumas ainda estavam em desenvolvimento. Também menciona iniciativas de indicadores e guias de transparência. O compromisso é permitir [[escrutínio de resultados e limitações]], sem confundir mais remoções ou mais denúncias com proteção efetivamente melhor.',
  [36], ['Principle 3.4', 'Good practice note (Principle 3.4)']);
add(29, 'Como o SbD 3.5 entende investimento e compartilhamento de tecnologia protetora, e quais boas práticas cita?',
  'O 3.5 pede compromisso de [[inovar, investir, colaborar e compartilhar]] ferramentas, tecnologia e boas práticas que ampliem a segurança. O relatório reconhece o potencial de tecnologias como aprendizado de máquina, mas coloca o investimento em uma agenda cooperativa de enfrentamento de danos. A nota histórica menciona participação em alianças e consórcios internacionais voltados à proteção de menores, como WePROTECT e ICT Coalition for Children Online. A participação ilustra cooperação entre organizações; não prova eficácia de cada ferramenta nem substitui avaliação. O princípio amplia a responsabilidade para [[a capacidade coletiva do setor]], evitando que o conhecimento de proteção fique restrito a uma organização.',
  [36], ['Principle 3.5', 'Good practice note (Principle 3.5)']);

add(30, 'No diagnóstico do SbD, como distinguir conteúdo, contato e conduta como riscos das cinco categorias de possíveis danos?',
  'A classificação de riscos distingue [[conteúdo]] indesejado ou inadequado recebido pela criança, [[contato]] em comunicação arriscada e [[conduta]] na qual seu comportamento contribui para conteúdo ou contato de risco. O relatório também organiza cinco possíveis danos: conteúdo ilegal; conteúdo inadequado à idade; outros conteúdos perigosos que possam produzir dano pessoal; conteúdo enganoso; e conduta pessoal ilegal ou danosa, como assédio. Essas classificações orientam o que examinar, mas não autorizam igualar exposição a dano realizado. O texto afirma que a pesquisa ainda busca compreender [[por que o risco se converte em dano para determinadas pessoas]], inclusive fatores que aumentam suscetibilidade.',
  [5], ['II. Background', 'Theoretical models of online harm and risks']);
add(31, 'Por que incorporar segurança desde a arquitetura modifica o trabalho de desenvolvimento em comparação com remediar danos depois?',
  'A introdução sustenta que arquitetura e desenho governam como as pessoas interagem, tornando desenvolvedores, engenheiros e fornecedores participantes na configuração do ambiente. Propõe [[considerar conscientemente a segurança como parte do desenvolvimento e da gestão de riscos]], em vez de encaixar proteções somente após o dano. O framework oferece recursos para integrar direitos e proteção à funcionalidade; seus princípios devem acompanhar desenho, desenvolvimento e disponibilização. Essa antecipação não promete eliminar todos os danos: altera [[o momento e a responsabilidade das decisões]], de resposta tardia a avaliação de riscos durante a criação, com revisão ao longo do ciclo de vida.',
  [3,4,22], ['I. Introduction', 'Principle 1: Service provider responsibilities']);
add(32, 'Por que o SbD pede humanos no circuito de denúncia automatizada e comunicação ao usuário sobre a automação?',
  'No 1.3, o relatório diz que algoritmos, filtros e outros sistemas automatizados precisam manter [[pessoas no circuito de supervisão]]. Essa supervisão permite revisar expectativas éticas, morais e sociais e ajustar os sistemas conforme a comunidade muda. O uso da automação também deve ser comunicado claramente. Assim, a triagem pode ganhar escala sem tornar seus critérios invisíveis ou dispensar governança. A presença de um algoritmo não resolve por si só a legitimidade da decisão: [[a avaliação humana e a transparência são partes do mecanismo de segurança]], junto de canais acessíveis e prioridades de encaminhamento.',
  [24], ['Principle 1.3']);
add(33, 'Como o SbD 1.6 trata mudanças no uso, perfis de risco e a presença de crianças fora dos serviços dirigidos a elas?',
  'O documento explica que fluxos de moderação precisam evoluir com popularidade, usos e informações sobre abuso. Limiares podem variar conforme conteúdo, conduta e perfil, e auditorias devem acompanhar mudanças. Serviços infantis costumam ter menor tolerância ao risco e recorrer à pré-moderação. Contudo, crianças também acessam serviços inadequados à idade; por isso, [[serviços não dirigidos a crianças não devem ignorar essa presença]]. O raciocínio sustenta gestão de riscos contínua e contextual, sem concluir que os mesmos controles terão efeito idêntico em todo produto. A revisão do perfil e das evidências é tão importante quanto [[a avaliação anterior ao lançamento]].',
  [27], ['Principle 1.6']);
add(34, 'Que diferença o SbD estabelece entre obter consentimento formal e construir compreensão de obrigações recíprocas no cadastro?',
  'O 1.7 desloca a ênfase do simples consentimento para [[obrigações recíprocas do serviço e dos participantes]]. Um contrato social deve ajudar a compreender práticas de proteção e a própria contribuição para uma comunidade segura. O exemplo do Safety Pledge inclui ensino das regras por introdução, tutoriais e dicas antes da participação. Assim, o aceite deixa de ser tratado como evidência suficiente de compreensão. Também não significa que quem aceita regras renuncia à segurança: o próprio texto afirma que usuários não abrem mão dela para acessar o serviço. Essa distinção exige [[comunicação e aprendizagem]], não apenas mais uma etapa burocrática de cadastro.',
  [28], ['Principle 1.7', 'Good practice note (Principle 1.7)']);
add(35, 'O que o exemplo do Quizlet permite discutir sobre calibrar proteção a diferentes produtos de uma mesma organização?',
  'A nota do 1.8 descreve proteção de dados, privacidade e segurança do usuário sob um departamento unificado de [[Trust and Safety]], que participa da revisão de iniciativas de produto e negócio. O exemplo não termina em uma regra única: filtros de linguagem eram calibrados segundo a sensibilidade e os riscos de cada produto, com maior rigor no Quizlet Live pelo caráter interativo ao vivo. A lição ilustrada é [[coerência de princípios com adaptação ao contexto]], não uniformidade mecânica de controles. Trata-se do arranjo descrito em maio de 2019; ele não demonstra por si só eficácia nem permite afirmar a estrutura atual do serviço.',
  [29], ['Good practice note (Principle 1.8)']);
add(36, 'Como os alertas do SbD podem criar espaço de reflexão sem transformar toda exposição sensível em remoção obrigatória?',
  'O 2.3 distingue entre remover conteúdo ilegal e empregar [[avisos, barreiras etárias e sinais de risco]] em outras situações, permitindo acesso por decisão informada quando cabível. A ação antecipada deve dar oportunidade de avaliar a situação e de adotar precauções. A nota de boas práticas caracteriza alertas como instantâneos, específicos, relevantes, privados e apoiadores, não meros obstáculos genéricos. Essa combinação permite discutir segurança com agência: o serviço orienta no momento relevante e oferece informação e controle. Não equivale a presumir que qualquer aviso resolve o risco, nem a confundir [[proteção com exclusão indistinta de conteúdos]].',
  [32], ['Principle 2.3', 'Good practice note (Principle 2.3)']);
add(37, 'Por que um sistema de denúncias pode exigir apoio ao bem-estar de quem denuncia, mesmo após a decisão sobre o conteúdo?',
  'O 2.4 reconhece que uma resposta holística deve tratar a ocorrência e [[encaminhar a pessoa a outras formas de apoio]]. Denunciar pode deixar o usuário exposto ou visível, de modo que o bem-estar não se reduz à remoção ou permanência do conteúdo. Informar andamento, resultado e possibilidade de recurso pode contribuir para confiança nos mecanismos. A nota descreve recursos de apoio e histórico de denúncias como ilustrações. Assim, é necessário separar [[a decisão de moderação e as necessidades de cuidado do denunciante]], sem apresentar apoio informacional como tratamento clínico ou como prova de recuperação do bem-estar.',
  [33], ['Principle 2.4', 'Good practice note (Principle 2.4)']);
add(38, 'Como diferenciar a nomeação de uma equipe de segurança da incorporação de segurança à cultura de trabalho no SbD?',
  'O 1.1 torna responsáveis identificáveis e mensuráveis; o 3.1 amplia [[formação e práticas a toda a força de trabalho]], inclusive terceiros e temporários. Uma equipe especializada pode investigar e definir políticas, enquanto pessoas de outras funções tomam decisões cotidianas que também afetam proteção. O exemplo da LEGO combina curso introdutório, aprofundamento direcionado e avaliações anuais comunicadas à liderança. A correlação interna ao SbD mostra que [[responsabilidade especializada e cultura distribuída são complementares]]. Ter uma equipe não demonstra que os demais fluxos adotem os princípios, e disseminar valores sem responsáveis concretos tampouco garante ação.',
  [22,34], ['Principle 1.1', 'Principle 3.1', 'Good practice note (Principle 3.1)']);
add(39, 'Quais cinco métricas da nota SbD 3.4 ajudam a decompor a avaliação de moderação e quais estavam em desenvolvimento em 2019?',
  'A nota apresenta cinco medidas de aplicação de padrões comunitários: [[prevalência das violações]], quantidade de conteúdo com ação, quantidade identificada por tecnologia e equipes antes de denúncia dos usuários, velocidade da ação conforme impacto e precisão das ações baseada em revisões. [[Velocidade e precisão estavam em desenvolvimento]] no exemplo de 2019. Separar essas dimensões evita usar só o volume de remoções como sinônimo de sucesso: maior detecção e menor prevalência, por exemplo, respondem a perguntas diferentes. O relatório recomenda análise significativa da eficácia das normas, não apenas publicar contagens. As métricas descritas são históricas e não uma medição atual desses serviços.',
  [36], ['Good practice note (Principle 3.4)', 'Principle 3.4']);
add(40, 'Que tensão a consulta juvenil do SbD revelou entre reconhecer utilidade do monitoramento e sentir-se confortável com ele?',
  'Na consulta relatada, [[71%]] consideraram útil o monitoramento de mensagens e conteúdo em segundo plano para prevenir experiências negativas, mas [[57%]] se disseram desconfortáveis com essas funções. Uma parcela achava os recursos invasivos e outra não tinha certeza sobre sua efetividade. Esses resultados mostram que reconhecer possível proteção não equivale a consentimento confortável nem a confiança demonstrada. O mesmo trecho destaca pedidos de transparência sobre armazenamento, uso e terceiros com acesso às informações. A interpretação fica restrita à consulta descrita: ela sustenta discutir [[controle, informação e intrusão conjuntamente]], sem generalizar percentuais a todos os jovens ou a qualquer tecnologia.',
  [16], ['IV. Consultation process']);
add(41, 'Como a diferença entre conhecimento de recursos de controle e de apoio orienta a comunicação de segurança no SbD?',
  'O fórum descrito registrou maior conhecimento de recursos de [[controle (98%) e monitoramento (93%)]] e menor de recursos ligados a violação de regras (84%) e apoio (64%). A página também relata valorização do controle e desconforto quando bloqueio não impede certas visualizações do perfil. Esses achados ajudam a perguntar se o usuário conhece tanto o mecanismo quanto seus limites e os caminhos de apoio. Não basta oferecer recursos invisíveis ou cuja capacidade seja mal compreendida. Os percentuais descrevem o grupo consultado, e não uma avaliação universal de eficácia; a implicação analítica é [[comunicar alcance, limitações e alternativas de cuidado]].',
  [15], ['Awareness and importance of safety features']);
add(42, 'Por que a consulta industrial do SbD favoreceu princípios flexíveis em vez de uma lista única de controles para todos?',
  'Participantes apontaram que serviços diferem em desenho, função, cultura, uso e modelos de negócio, e que recursos eficazes em uma comunidade podem não ter o mesmo efeito em outra. Também pediram atenção a [[linguagem, cultura, idade, gênero, capacidade e outras diferenças]], sem concentrar proteção apenas na infância. A flexibilidade buscava evitar tratar o framework como checklist de conformidade ou impor mecanismos rapidamente ultrapassados. Isso não elimina o compromisso com direitos e proteção: sugere [[especificar o objetivo e justificar os meios conforme o contexto]]. O texto relata posições e tensões da consulta, sem provar que qualquer implementação flexível produzirá melhores resultados.',
  [19], ['IV. Consultation process', 'Industry']);
add(43, 'Que objeções e consensos sobre transparência de métricas surgiram na consulta do SbD, e por que isso exige interpretação contextual?',
  'Representantes industriais temiam que publicar detalhes e números permitisse manipular sistemas ou induzisse comparações equivocadas entre plataformas. Também houve dúvidas sobre converter métricas padronizadas em comparações significativas para usuários. Ao mesmo tempo, o relatório registra acordo sobre [[transparência das políticas, processos e práticas de moderação]] como meio de informar e empoderar. A tensão não se resolve trocando análise por contagem: é preciso explicar contexto, limites e o que cada indicador mede. Isso aproxima transparência de [[inteligibilidade e prestação de contas]], sem supor que qualquer número publicado permita comparar serviços ou demonstrar eficácia.',
  [19,20], ['IV. Consultation process', 'Industry']);

add(44, 'Como relacionar a prevenção do SbD à redefinição de Radiant Patterns sem prometer ausência de toda experiência negativa?',
  'Como [[comparação entre os textos]], o SbD pede avaliar danos conhecidos e antecipados no desenho do serviço, enquanto Operationalizing concentra a definição refinada em minimizar riscos previsíveis de dano psicológico e evitar padrões que frustrem autonomia, competência e vínculo. Os dois deslocam a proteção para escolhas de design, mas não fornecem a mesma especificação: SbD abrange governança e segurança do serviço; os RPs detalham necessidades psicológicas no jogo. O artigo rejeita a meta improvável de eliminar toda experiência negativa. Portanto, [[prevenir dano não implica abolir desafio ou tensão]], nem a afinidade conceitual comprova eficácia de uma implementação.',
  [22], ['Principle 1: Service provider responsibilities'], [[oper,[7],['4 Revisiting and Reshaping Game Radiant Patterns']]]);
add(45, 'Como a avaliação de riscos do SbD pode orientar uma análise de World Creation, e o que ainda precisa ser demonstrado?',
  'A leitura conjunta permite usar [[avaliação documentada de riscos]] do SbD para perguntar quais decisões de uma ferramenta criativa facilitam danos. Operationalizing oferece critérios concretos: ferramentas essenciais, salvar e compartilhar criações não devem depender de pagamento ou grind excessivo; recursos obscuros e mal documentados podem minar competência e autonomia. A relação é uma proposta analítica: registrar barreiras, grupos afetados e alternativas antes do lançamento, revisando riscos com o uso. Ela não foi testada nesses textos como protocolo integrado, e o artigo reconhece a necessidade de [[avaliar efeitos reais em diferentes perfis de jogador]]. Conformidade descritiva não é prova de bem-estar.',
  [27], ['Principle 1.6'], [[oper,[12,14],['Watch For', '6 Challenges, Perspectives and Limitations']]]);
add(46, 'Que relação pode ser traçada entre engajamento aberto do SbD e o refinamento colaborativo do framework de Radiant Patterns?',
  'O SbD 3.3 recomenda expor padrões a usuários, especialistas independentes e partes interessadas para descobrir consequências e lacunas. No framework de RPs, sessões de refinamento discutem formulações e casos-limite, registram desacordos e mantêm histórico de versões até uma formulação estável. A correlação está em [[usar crítica e documentação para tornar critérios revisáveis]]. Contudo, o estudo reconhece que o consenso especializado é ponto de partida para validação mais ampla. Assim, um grupo pode melhorar clareza e coerência sem representar todos os jogadores nem demonstrar impacto psicológico; [[abertura, diversidade e teste de efeitos]] continuam necessários.',
  [35], ['Principle 3.3'], [[hci,[7],['3.2 Phase II: Curated Refinement Sessions', '3.3 Phase III: Exploratory Autoethnography']]]);
add(47, 'Como evitar que o framework de níveis de Radiant Patterns vire um checklist incompatível com o caráter contextual do SbD?',
  'A consulta do SbD rejeita soluções únicas para produtos heterogêneos e pede adaptação a funções, comunidades e modelos de negócio. HCI Games descreve níveis e variantes específicas de contexto; na discussão, L1 é uma [[base defensiva]], sobre a qual L2 e L3 acrescentam apoio ativo. A comparação sugere tratar níveis como estrutura para justificar escolhas e suas consequências, não como selo automático. O artigo distingue a perspectiva de nove especialistas de um consenso global da indústria. Logo, [[estrutura comum e contextualização podem coexistir]], mas nenhuma classificação dispensa avaliar adequação à população e efeitos reais do design.',
  [19], ['IV. Consultation process', 'Industry'], [[hci,[14],['6 Discussion: Radiant Patterns and Industry Practice']]]);
add(48, 'Como as responsabilidades organizacionais do SbD ajudam a interpretar os limites de ferramentas éticas para desenvolvedores propostos na agenda de intervenção?',
  'O SbD 1.1 atribui responsáveis mensuráveis e destaca o papel da liderança em valores e direção. A agenda de intervenção observa que monetização pode ser decidida por executivos, acionistas e equipes de produto, deixando designers com pouca autonomia mesmo quando conhecem os problemas. A correlação é que [[uma ferramenta não substitui a distribuição de poder e responsabilidade]]. Ela pode apoiar decisões, mas não garante autorização para rejeitar uma prática lucrativa. A agenda pede investigação empírica dessas pressões; a leitura conjunta sugere investigar quem pode alterar diretrizes e indicadores, sem afirmar que nomear uma equipe por si só resolve o conflito.',
  [22], ['Principle 1.1'], [[agenda,[10],['3.2 Development of Software Artifacts to Foster Real-Time Awareness on Users and Developers']]]);
add(49, 'Que distinção entre quantidade de denúncias e impacto no bem-estar conecta SbD 3.4 à agenda de avaliação em jogos?',
  'SbD 3.4 pede análise da eficácia das regras e moderação, para além da escala de denúncias. A agenda propõe instrumentos que capturem [[autonomia percebida, justiça, transparência, respeito e bem-estar]], com medidas comportamentais e qualitativas. A relação é metodológica: contar ocorrências e ações descreve atividade, enquanto avaliar mudança na experiência responde a outra pergunta. Um serviço pode moderar muito sem demonstrar menor coerção ou melhor bem-estar. Essa combinação é uma [[proposta de leitura e avaliação]], não uma bateria conjunta já validada pelos trabalhos; escolha de medidas e relação causal precisam de investigação específica.',
  [36], ['Principle 3.4'], [[agenda,[11],['3.3 Advancing Methods and Measures for Assessing Dark Pattern Prevalence and Player Experience, Including Well-Being']]]);
add(50, 'Como alertas de risco do SbD e ferramentas de apoio ao jogador podem preservar autonomia sem produzir nova manipulação?',
  'O SbD 2.3 propõe sinais de risco relevantes e oportunidade de reflexão. A agenda imagina ferramentas contextuais que expliquem mecanismos enganosos e ajudem escolhas informadas, mas adverte contra [[enganar o usuário para fazê-lo escolher melhor]], impor decisões, excesso de alertas, falsos positivos e intrusão. A correlação permite avaliar tanto a intenção protetora quanto a experiência criada pela intervenção: informar, oferecer alternativas e manter escolha não é o mesmo que dirigir coercivamente. Essas ferramentas são [[propostas que exigem teste]], e as notas SbD são ilustrações; nenhum dos textos demonstra que qualquer aviso, por ser protetor na intenção, preserve automaticamente autonomia.',
  [32,21], ['Principle 2.3', 'Good practice note (Principle 2.3)', 'V. Safety by Design Principles'], [[agenda,[9,10],['3.2 Development of Software Artifacts to Foster Real-Time Awareness on Users and Developers']]]);
add(51, 'Como a exigência SbD de políticas compreensíveis problematiza Untranslation nas aplicações brasileiras estudadas?',
  'SbD 3.2 pede linguagem clara e informação acessível, inclusive a usuários jovens. O estudo brasileiro descreve [[Untranslation]] como uso de língua estrangeira para obscurecer informação em um aplicativo predominantemente na língua do usuário. A leitura comparativa mostra que disponibilizar texto não basta para torná-lo compreensível: a barreira linguística pode reduzir condições de escolha e acesso à proteção. Entretanto, o estudo cobre aplicativos gratuitos em alta, dez minutos de uso inicial e emulação. Assim, a relação é um [[critério crítico de inteligibilidade]], não prova de que uma tradução específica elimina padrões ou reduz dano, nem afirmação de que os apps foram avaliados segundo o SbD.',
  [34,35], ['Principle 3.2'], [[inter,[7,8],['4 Discussions', '5 Limitations']]]);
add(52, 'Como uma auditoria inicial de dark patterns pode alimentar a gestão de risco SbD sem substituí-la?',
  'A auditoria brasileira identifica ocorrências em um recorte delimitado de primeiro uso, com limitações de tempo e emulação. SbD 1.6 pede avaliações documentadas e fluxos que evoluam com novas informações e usos. A relação é que [[um inventário de padrões pode informar hipóteses de risco]], prioridades e perguntas para acompanhamento, mas não encerra a avaliação: outros momentos e públicos podem expor mecanismos distintos. Tampouco ocorrência de um padrão demonstra automaticamente dano psicológico individual ou eficácia de sua remoção. Uma leitura orientada ao bem-estar deve separar [[detecção, exposição, consequências e efeito da intervenção]], verificando cada uma com evidência apropriada.',
  [27], ['Principle 1.6'], [[inter,[8],['5 Limitations', '6 Conclusion']]]);
add(53, 'Como desenho inclusivo no SbD se relaciona à crítica do creator-consumer divide sem reduzir desigualdade a diferenças individuais?',
  'SbD 2.5 exige considerar características e capacidades distintas e avaliar exclusões antes de lançar funções; a consulta inclui linguagem, cultura e condições diversas. CHIP propõe o [[creator-consumer divide]] para analisar vulnerabilidades sistêmicas anteriores ao jogo e capitalizadas por direcionamento deliberado ou automação indiferente. A comparação amplia a pergunta de inclusão: não apenas se uma pessoa consegue operar um recurso, mas se decisões feitas em um contexto exploram precariedade de outro. O artigo é teórico e especulativo; por isso, a correlação sustenta [[perguntas de avaliação contextual]], sem transformar o cenário de Helena em observação empírica ou atribuir ao SbD uma explicação causal que ele não testou.',
  [19,33], ['IV. Consultation process', 'Principle 2.5'], [[chip,[1,2],['2 The Creator-Consumer Divide as a Lens for Understanding Systemic Player Vulnerability', '3 A Speculative Perspective: Helena and The Gilded Cage of Ouroboros Seed']]]);
add(54, 'Como protocolos por jurisdição e participação aberta do SbD podem ser tensionados pela arbitragem regulatória discutida em CHIP?',
  'O SbD 1.4 exige protocolos referentes às jurisdições e caminhos de apoio locais; o 3.3 recomenda interlocução externa. CHIP argumenta que assimetrias de poder e proteção podem permitir [[arbitragem regulatória]], ilustrada em cenário especulativo de tecnologia proibida na origem e aplicada no Brasil. A leitura conjunta permite questionar se cumprir formalidades locais basta quando a vulnerabilidade e a capacidade de contestação são desiguais. Não se trata de demonstrar que uma plataforma real praticou esse deslocamento: é uma [[tensão normativa e investigativa]], que sugere ouvir comunidades afetadas e examinar decisões transnacionais, sem oferecer diagnóstico jurídico de vigência.',
  [25,35], ['Principle 1.4', 'Principle 3.3'], [[chip,[2],['2 The Creator-Consumer Divide as a Lens for Understanding Systemic Player Vulnerability', '3 A Speculative Perspective: Helena and The Gilded Cage of Ouroboros Seed']]]);
add(55, 'Por que classificar uma plataforma no documento Art.48 e implementar Safety by Design são tarefas relacionadas, mas diferentes?',
  'O documento local do Art.48 considera conteúdo de usuários como referência para a classificação da plataforma e inclui controle editorial, controles parentais e políticas de moderação entre elementos da classificação final. SbD recomenda [[processos de prevenção, gestão de riscos, suporte e responsabilização]]. A relação é que recursos e políticas podem informar uma avaliação do serviço, mas atribuir uma faixa etária não é o mesmo que implementar e avaliar esses processos. A comparação não afirma vigência do Art.48 nem equivalência de escopos. [[Classificação, operação protetora e efeitos no bem-estar]] são questões distintas que precisam de evidências próprias.',
  [22,27], ['Principle 1: Service provider responsibilities', 'Principle 1.6'], [[art,[2,4,5],['Art.48, §3º', 'Art.48, §14', 'Art.48, §15']]]);
add(56, 'Como a manutenção prolongada de atividade no Art.48 pode ser analisada à luz de autonomia e controle no SbD?',
  'O Art.48 local lista funções que incentivam permanência prolongada, como rolagem infinita, notificações constantes, recompensas variáveis e reprodução automática, entre elementos para classificação. SbD 2.1 recomenda [[controle da própria experiência e padrões iniciais protetores]]. A relação comparativa permite perguntar se a pessoa dispõe de escolhas e controles efetivos diante de mecanismos de continuidade. A mera presença de um recurso na lista não prova dano individual, e o SbD não oferece nessa passagem uma avaliação experimental de cada mecanismo. Assim, [[identificar uma funcionalidade e julgar seu efeito sobre autonomia]] exigem etapas diferentes; a correlação não demonstra vigência nem define automaticamente uma faixa etária.',
  [30], ['Principle 2.1'], [[art,[4],['Art.48, §10, XX']]]);
add(57, 'Como combinar colaboração SbD, documentação compartilhada e refinamento de RPs sem confundir diálogo com validação empírica?',
  'SbD 3.3 e 3.5 defendem abertura e cooperação; a agenda propõe [[curadoria, revisão por pares e versionamento]] de conhecimento aplicável; o estudo HCI registra desacordos e revisões de formulações. Em conjunto, eles permitem pensar uma infraestrutura em que critérios, exemplos e decisões possam ser criticados e atualizados. Porém, consenso torna a descrição mais coerente, não demonstra benefício longitudinal nem adequação universal. A relação aqui formulada é analítica: [[diálogo documentado e avaliação de efeitos cumprem funções complementares]]. Participação e versões podem apoiar a qualidade do conhecimento, enquanto estudos apropriados ainda precisam testar resultados e limitações.',
  [35,36], ['Principle 3.3', 'Principle 3.5'], [[agenda,[8],['3.1 Collaboration to Document Positive Patterns and Share Working Examples of Ethical Game Design Elements']], [hci,[7],['3.2 Phase II: Curated Refinement Sessions', '3.3 Phase III: Exploratory Autoethnography']]]);
add(58, 'Que cautela comum deve acompanhar boas práticas SbD, casos de Untranslation e soluções radiantes ao montar uma argumentação sobre bem-estar?',
  'Os documentos oferecem [[tipos diferentes de evidência]]. SbD avisa que suas notas são ilustrações sem evidência robusta de efetividade e impacto; Interact descreve padrões observados em um recorte de aplicativos e reconhece limites de uso inicial e emulação; Operationalizing propõe critérios de design e pede avaliar efeitos em perfis distintos. A correlação permite construir uma cadeia de perguntas: qual problema foi observado, qual resposta é proposta, para quem e com que evidência de efeito? Não autoriza concluir que a mera oposição a um padrão garante bem-estar. [[Diagnóstico, orientação e validação de intervenção]] devem permanecer distinguíveis mesmo quando contribuem para uma mesma agenda preventiva.',
  [21], ['V. Safety by Design Principles'], [[inter,[8],['5 Limitations', '6 Conclusion']], [oper,[14],['6 Challenges, Perspectives and Limitations']]]);

if (rows.length !== 50 || new Set(rows.map(x => x.id)).size !== 50) throw Error('Quantidade ou IDs incorretos');
fs.mkdirSync(out, {recursive: true});
fs.writeFileSync(path.join(out, main + '.json'), JSON.stringify(rows, null, 2) + '\n', 'utf8');
console.log(rows.length + ' candidatos: ' + rows.filter(x => x.kind === 'direct').length + ' diretos e ' + rows.filter(x => x.kind === 'synthesis').length + ' sínteses.');
